mapper.select:
select b.batch_id, b.batch_no, b.buyer_id, b.station_id, b.gas_type, b.purchase_date, b.qty, b.unit_price,
       b.amount, b.pay_status, b.invoice_status, b.invoice_no, b.invoiced_at, b.version,
       b.create_by, b.create_time, b.update_by, b.update_time, b.remark,
       s.station_code, s.station_name, bu.buyer_name,
       ifnull(r.received_qty, 0) as received_qty,
       ifnull(p.paid_amount, 0) as paid_amount
from gas_purchase_batch b
left join gas_station s on b.station_id = s.station_id
left join gas_buyer bu on b.buyer_id = bu.buyer_id
left join (select batch_id, sum(qty) as received_qty from gas_purchase_receipt group by batch_id) r on r.batch_id = b.batch_id
left join (select batch_id, sum(amount) as paid_amount from gas_purchase_payment group by batch_id) p on p.batch_id = b.batch_id


		AND b.batch_no like concat('%', #{batchNo}, '%')


		AND b.buyer_id = #{buyerId}


		AND b.station_id = #{stationId}


		AND b.gas_type = #{gasType}


		AND b.pay_status = #{payStatus}


		AND b.invoice_status = #{invoiceStatus}


		AND b.purchase_date >= #{params.beginDate}


		AND b.purchase_date <= #{params.endDate}


order by b.purchase_date desc, b.batch_id desc

mapper.update:
update gas_purchase_batch
batch_no = #{batchNo}, station_id = #{stationId}, buyer_id = #{buyerId}, gas_type = #{gasType}, purchase_date = #{purchaseDate}, qty = #{qty}, unit_price = #{unitPrice}, amount = #{amount}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where batch_id = #{batchId} and version = #{version}

update gas_purchase_batch
set pay_status = #{payStatus}, version = version + 1, update_time = sysdate()
where batch_id = #{batchId}
